import sys
import json
import os

# Add skill path
sys.path.append('/root/.gemini/skills/mesh-analysis/scripts')

try:
    from mesh_tool import MeshAnalyzer
except ImportError:
    # Fallback to checking other locations if .gemini path fails (though it should exist based on `ls`)
    sys.path.append('/root/.claude/skills/mesh-analysis/scripts')
    try:
        from mesh_tool import MeshAnalyzer
    except ImportError:
        print("Could not find mesh_tool module in expected paths.")
        sys.exit(1)

stl_path = '/root/scan_data.stl'
density_table_path = '/root/material_density_table.md'
output_path = '/root/mass_report.json'

def get_density_from_table(file_path, material_id):
    with open(file_path, 'r') as f:
        lines = f.readlines()

    for line in lines:
        if line.strip().startswith('|'):
            parts = [p.strip() for p in line.split('|')]
            # Format: | Material ID | Material Name | Density | ... |
            # parts[0] is empty, parts[1] is ID, parts[2] is Name, parts[3] is Density
            if len(parts) > 3:
                try:
                    # Remove ** ** if present
                    id_text = parts[1].replace('*', '')
                    # Skip header line which won't convert to int
                    if not id_text.isdigit():
                        continue

                    if int(id_text) == material_id:
                        return float(parts[3])
                except ValueError:
                    continue
    return None

def main():
    if not os.path.exists(stl_path):
        print(f"Error: STL file not found at {stl_path}")
        sys.exit(1)

    print("Initializing MeshAnalyzer...")
    try:
        analyzer = MeshAnalyzer(stl_path)
    except Exception as e:
        print(f"Failed to initialize MeshAnalyzer: {e}")
        sys.exit(1)

    print("Analyzing largest component...")
    try:
        report = analyzer.analyze_largest_component()
    except Exception as e:
        print(f"Analysis failed: {e}")
        sys.exit(1)

    volume = report.get('main_part_volume')
    material_id = report.get('main_part_material_id')

    if volume is None or material_id is None:
        print("Error: Report did not contain volume or material_id")
        print(report)
        sys.exit(1)

    print(f"Volume: {volume}")
    print(f"Material ID: {material_id}")

    density = get_density_from_table(density_table_path, material_id)

    if density is None:
        print(f"Error: Density for Material ID {material_id} not found in table.")
        sys.exit(1)

    print(f"Density: {density}")

    mass = volume * density
    print(f"Calculated Mass: {mass}")

    output_data = {
        "main_part_mass": round(mass, 2),
        "material_id": material_id
    }

    with open(output_path, 'w') as f:
        json.dump(output_data, f, indent=1)

    print(f"Report written to {output_path}")

if __name__ == "__main__":
    main()

